const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}

return [{ json: { decision: 'VALID', request_id: body.request_id } }];

const merge = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(merge) ? merge[0] : merge;

if (!mergeRow) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MERGE_REQUEST_NOT_FOUND',
    message: 'No merge_requests row found for this request_id.'
  }}];
}

const itemsInput = $('Fetch Items').all();
let items;
if (itemsInput.length === 1 && Array.isArray(itemsInput[0].json)) {
  items = itemsInput[0].json;
} else {
  items = itemsInput.map(function(i) { return i.json; });
}

if (!items || items.length === 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'NO_ITEMS_FOUND',
    request_id: mergeRow.request_id,
    message: 'No merge_request_items rows found for this request_id.'
  }}];
}

const missingParentSku = items.filter(function(i) { return !i.parent_sku; });
if (missingParentSku.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_PARENT_SKU',
    request_id: mergeRow.request_id,
    message: 'One or more items have no parent_sku stored. Cannot build a real feed without it.',
    affected_skus: missingParentSku.map(function(i) { return i.sku; })
  }}];
}

// Switched from "add" to "replace" for every patch here - two real,
// confirmed-working submissions found today both used "replace" for
// setting listing attributes via PATCH (Amazon's own migration
// tutorial, and a third-party guide with a confirmed ACCEPTED
// response), while every real submission this project has made so far
// used "add" exclusively and failed every time with a generic
// BAD_REQUEST. Not proven yet against a real call of our own - the
// attribute paths themselves are already confirmed valid (a separate
// real report showed "delete" succeeding on these same two attributes,
// parentage_level and child_parent_sku_relationship, for the reverse
// operation) - this is the one remaining common factor untested until now.
// Amazon's real theme-name format is already underscore/uppercase (COLOR,
// SIZE, ITEM_LENGTH, ...) straight from the live PTD API - no CamelCase
// conversion needed, unlike the legacy flat-file format.
const themeName = mergeRow.dimension2_theme
  ? mergeRow.dimension1_theme + '/' + mergeRow.dimension2_theme
  : mergeRow.dimension1_theme;

const mkId = mergeRow.marketplace_id;

// Verified against the real, current JSON_LISTINGS_FEED v2 schema
// (amzn/selling-partner-api-models, schemas/feeds/listings-feed-schema-v2.json)
// before this was ever wired to a real submission trigger. The shape
// this project built throughout - a top-level "body" object holding one
// shared "operationType" plus a "listings" array - does not exist in
// the real schema at all. The real schema has no "body" wrapper: each
// entry is a "message" inside a top-level "messages" array, each with
// its own operationType and a required, submission-unique messageId.
// Everything else (sku, productType, patches) was already correct.
// Builds the correctly-shaped array value for an attribute PATCH, given a
// raw value that might be simple (a string/number) or structured (an
// object with its own sub-fields, e.g. footwear_size/shirt_size).
// Structured attributes have no "value" property in their real schema at
// all - size/size_class/size_system etc. sit as direct sibling fields on
// the entry - wrapping one in {value: ...} is exactly what got a real
// FG92 submission rejected by Amazon. Mirrors how parentAttributes
// already handles this correctly when copying straight from the anchor's
// own attributes.
function buildAttributeEntry(rawValue, marketplaceId) {
  if (rawValue !== null && typeof rawValue === 'object' && !Array.isArray(rawValue)) {
    return [Object.assign({}, rawValue, { marketplace_id: marketplaceId })];
  }
  return [{ value: rawValue, marketplace_id: marketplaceId }];
}

const messages = items.map(function(item, index) {
  const patches = [
    { op: 'replace', path: '/attributes/parentage_level', value: [{ value: 'child', marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/child_parent_sku_relationship', value: [{ child_relationship_type: 'variation', parent_sku: item.parent_sku, marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/variation_theme', value: [{ name: themeName, marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/' + mergeRow.dimension1_attribute, value: buildAttributeEntry(item.dimension1_value, mkId) }
  ];

  if (mergeRow.dimension2_attribute && item.dimension2_value) {
    patches.push({ op: 'replace', path: '/attributes/' + mergeRow.dimension2_attribute, value: buildAttributeEntry(item.dimension2_value, mkId) });
  }

  return {
    messageId: index + 1,
    sku: item.sku,
    operationType: 'PATCH',
    productType: item.normalized_product_type || 'PRODUCT',
    patches: patches
  };
});

const jsonPayload = {
  header: {
    sellerId: mergeRow.seller_id,
    version: '2.0',
    issueLocale: 'en_US'
  },
  messages: messages
};

return [{ json: {
  decision: 'PAYLOAD_READY',
  request_id: mergeRow.request_id,
  parent_sku: items[0].parent_sku,
  child_count: messages.length,
  json_payload: jsonPayload
}}];
